import 'package:flutter/material.dart';
import '../../core/theme/app_theme.dart';
import '../../services/ml_api_service.dart';

class YieldPredictionScreen extends StatefulWidget { const YieldPredictionScreen({super.key}); @override State<YieldPredictionScreen> createState()=>_YieldPredictionScreenState(); }
class _YieldPredictionScreenState extends State<YieldPredictionScreen>{
 final f=GlobalKey<FormState>(); final year=TextEditingController(text:'2026'),area=TextEditingController(text:'10'),rain=TextEditingController(text:'800'),fert=TextEditingController(text:'100'),pest=TextEditingController(text:'10'); String crop='Rice',season='Kharif',state='Gujarat'; bool loading=false; String? result,error;
 @override void dispose(){for(final c in [year,area,rain,fert,pest])c.dispose();super.dispose();} double num(TextEditingController c)=>double.parse(c.text);
 Future<void> submit() async{if(!f.currentState!.validate())return;setState(() { loading=true; error=null; result=null; });try{final r=await MlApiService.yieldPrediction(crop:crop,cropYear:int.parse(year.text),season:season,state:state,area:num(area),annualRainfall:num(rain),fertilizer:num(fert),pesticide:num(pest));if(mounted)setState(()=>result=(r['predicted_yield'] ?? 'Result returned').toString() + ' ' + (r['unit'] ?? '').toString());}catch(e){if(mounted)setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Yield Prediction')),body:Form(key:f,child:ListView(padding:const EdgeInsets.all(18),children:[_box('Development model: its training data is synthetic and must not be treated as agronomic evidence.'),_drop('Crop',crop,['Rice','Wheat','Maize','Cotton','Chickpea','Groundnut','Sugarcane','Potato','Soybean','Millet'],(v)=>setState(()=>crop=v)),_field(year,'Crop year',true),_drop('Season',season,['Kharif','Rabi','Summer','Whole Year'],(v)=>setState(()=>season=v)),_drop('State',state,['Gujarat','Maharashtra','Punjab','Karnataka','Madhya Pradesh','Rajasthan','Uttar Pradesh','Bihar'],(v)=>setState(()=>state=v)),_field(area,'Area'),_field(rain,'Annual rainfall'),_field(fert,'Fertilizer'),_field(pest,'Pesticide'),FilledButton.icon(onPressed:loading?null:submit,icon:const Icon(Icons.insights),label:Text(loading?'Predicting…':'Predict Yield')),if(error!=null)_msg(c,error!,true),if(result!=null)_msg(c,'Predicted yield: $result',false)])));
 Widget _field(TextEditingController c,String l,[bool integer=false])=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextFormField(controller:c,keyboardType:integer?TextInputType.number:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:l),validator:(v)=>integer?(int.tryParse(v??'')==null?'Enter a valid year':null):(double.tryParse(v??'')==null?'Enter a valid number':null)));
 Widget _drop(String l,String v,List<String> items,ValueChanged<String> cb)=>Padding(padding:const EdgeInsets.only(bottom:12),child:DropdownButtonFormField<String>(value:v,decoration:InputDecoration(labelText:l),items:items.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>cb(x!)));
 Widget _box(String s)=>Container(margin:const EdgeInsets.only(bottom:16),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:AppTheme.lightGreen,borderRadius:BorderRadius.circular(18)),child:Text(s,style:const TextStyle(fontWeight:FontWeight.w700)));
 Widget _msg(BuildContext c,String s,bool e)=>Container(margin:const EdgeInsets.only(top:16),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:e?Theme.of(c).colorScheme.errorContainer:AppTheme.lightGreen,borderRadius:BorderRadius.circular(16)),child:Text(s,style:const TextStyle(fontWeight:FontWeight.w700)));
}
